package rules

import "testing"

// The expected output of every case comes from the PHP engine.
func TestLineLengthAttributes(t *testing.T) {
	t.Parallel()
	cases := []struct{ src, want string }{
		{"#[A(1, )]\nclass X {}", "#[A(1,)]\nclass X {}"},
		{"#[A( 1 )]\nclass X {}", "#[A(1)]\nclass X {}"},
		{"#[A(1, 2)]\nclass X {}", "#[A(1, 2)]\nclass X {}"},
		{"#[A(\n    1,\n    2\n)]\nclass X {}", "#[A(1, 2)]\nclass X {}"},
		{"#[A(\n    1,\n    2,\n)]\nclass X {}", "#[A(1, 2,)]\nclass X {}"},
		{"#[A(\n    x: 1,\n    y: 2,\n)]\nclass X {}", "#[A(x: 1, y: 2,)]\nclass X {}"},
		{"#[A(1, ), B(2, )]\nclass X {}", "#[A(1,), B(2, )]\nclass X {}"},
		{"#[A(\n    1\n), B(\n    2\n)]\nclass X {}", "#[A(1), B(\n    2\n)]\nclass X {}"},
		{"#[\n    A(1),\n    B(2),\n]\nclass X {}", "#[\n    A(1),\n    B(2),\n]\nclass X {}"},
		{"#[\n    A(\n        1\n    ),\n]\nclass X {}", "#[\n    A(1),\n]\nclass X {}"},
		{"#[\n    A,\n    B,\n]\nclass X {}", "#[\n    A,\n    B,\n]\nclass X {}"},
		{"#[\n    A\n]\nclass X {}", "#[\n    A\n]\nclass X {}"},
		{"#[A]\nclass X {}", "#[A]\nclass X {}"},
		{"#[A()]\nclass X {}", "#[A()]\nclass X {}"},
		{"#[A( )]\nclass X {}", "#[A()]\nclass X {}"},
		{"#[A(\n)]\nclass X {}", "#[A()]\nclass X {}"},
		{"#[A(\n    x: [1, 2],\n    y: 3\n)]\nclass X {}", "#[A(x: [1, 2], y: 3)]\nclass X {}"},
		{"#[A(\n    x: [\n        1,\n        2,\n    ]\n)]\nclass X {}", "#[A(x: [1, 2,])]\nclass X {}"},
		{"#[A(\n    new B(\n        1\n    )\n)]\nclass X {}", "#[A(new B(1))]\nclass X {}"},
		{"#[A(\n    ['k' => 1]\n)]\nclass X {}", "#[A(\n    ['k' => 1]\n)]\nclass X {}"},
		{"#[A(\n    k: ['k' => 1],\n    j: 2\n)]\nclass X {}", "#[A(\n    k: ['k' => 1],\n    j: 2\n)]\nclass X {}"},
		{"#[A(\n    // c\n    1\n)]\nclass X {}", "#[A(\n    // c\n    1\n)]\nclass X {}"},
		{"#[A(\n    /* c */\n    1\n)]\nclass X {}", "#[A(\n    /* c */\n    1\n)]\nclass X {}"},
		{"#[A(\n    1 // c\n)]\nclass X {}", "#[A(\n    1 // c\n)]\nclass X {}"},
		{"#[A(\n    <<<'T'\n    a\n    T\n)]\nclass X {}", "#[A(\n    <<<'T'\n    a\n    T\n)]\nclass X {}"},
		{"#[A(\n    'a\nb'\n)]\nclass X {}", "#[A('a\nb')]\nclass X {}"},
		{"class X {\n    #[A(\n        1,\n    )]\n    public $a;\n}", "class X {\n    #[A(1,)]\n    public $a;\n}"},
		{"class X {\n    #[A(1, )]\n    public function f() {}\n}", "class X {\n    #[A(1,)]\n    public function f() {}\n}"},
		{"function f(\n    #[A(\n        1\n    )]\n    $x\n) {}", "function f(#[A(1)] $x) {}"},
		{"function f(#[A(1, )] $x) {}", "function f(#[A(1,)] $x) {}"},
		{"$f = #[A(\n    1\n)] function () {};", "$f = #[A(1)] function () {};"},
		{"#[A\\B(\n    1\n)]\nclass X {}", "#[A\\B(1)]\nclass X {}"},
		{"#[\\A\\B(\n    1\n)]\nclass X {}", "#[\\A\\B(1)]\nclass X {}"},
		{"#[a(\n    1\n)]\nclass X {}", "#[a(1)]\nclass X {}"},
		{"#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}", "#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}"},
		{"#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}", "#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}"},
		{"#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}", "#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}"},
		{"#[A('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx')]\nclass X {}", "#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}"},
		{"#[A('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx')]\nclass X {}", "#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}"},
		{"#[A('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx')]\nclass X {}", "#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}"},
		{"#[A('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', )]\nclass X {}", "#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n)]\nclass X {}"},
		{"class X {\n    #[A(\n        'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n        'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n    )]\n    public $a;\n}", "class X {\n    #[A(\n        'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n        'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n    )]\n    public $a;\n}"},
		{"class X {\n    #[Foo('aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa', name: 'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb', methods: ['GET', 'POST'])]\n    public $a;\n}", "class X {\n    #[Foo('aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa', name: 'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb', methods: [\n        'GET',\n        'POST'\n    ])]\n    public $a;\n}"},
		{"class X {\n    #[Foo('aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa', name: 'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb', x: [1, 2])]\n    public $a;\n}", "class X {\n    #[Foo('aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa', name: 'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb', x: [\n        1,\n        2\n    ])]\n    public $a;\n}"},
		{"class X {\n    #[Foo('aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa', name: 'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb', [new B(1, 2)])]\n    public $a;\n}", "class X {\n    #[Foo('aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa', name: 'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb', [\n        new B(1, 2)\n    ])]\n    public $a;\n}"},
		{"#[A(\n                                                                                          new B('zzzzzzzzzzzzzzzzzzzz', 'zzzzzzzzzzzzzzzzzzzz')\n)]\nclass X {}", "#[A(\n                                                                                          new B(\n                                                                                            'zzzzzzzzzzzzzzzzzzzz',\n                                                                                            'zzzzzzzzzzzzzzzzzzzz'\n                                                                                        )\n)]\nclass X {}"},
		{"#[A(\n                                                                                          [1, 2, 'zzzzzzzzzzzzzzzzzzzzzzzzzzzzzz']\n)]\nclass X {}", "#[A(\n                                                                                          [\n                                                                                            1,\n                                                                                            2,\n                                                                                            'zzzzzzzzzzzzzzzzzzzzzzzzzzzzzz'\n                                                                                        ]\n)]\nclass X {}"},
		{"#[A(\n                                                                                          foo('zzzzzzzzzzzzzzzzzzzz', 'zzzzzzzzzzzzzzzzzzzz')\n)]\nclass X {}", "#[A(\n                                                                                          foo(\n                                                                                            'zzzzzzzzzzzzzzzzzzzz',\n                                                                                            'zzzzzzzzzzzzzzzzzzzz'\n                                                                                        )\n)]\nclass X {}"},
		{"#[A(/** d */ 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy')]\nclass X {}", "#[A(\n    /** d */ 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy'\n)]\nclass X {}"},
		{"#[A('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy' /** d */ )]\nclass X {}", "#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy' /** d */\n)]\nclass X {}"},
		{"foo(/** d */ 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy');", "foo(\n    /** d */ 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy'\n);"},
		{"#[A(array(\n    1,\n    2\n))]\nclass X {}", "#[A(array(\n    1,\n    2\n))]\nclass X {}"},
		{"#[A(\n    array(\n        1,\n        2\n    )\n)]\nclass X {}", "#[A(array(\n        1,\n        2\n    ))]\nclass X {}"},
		{"#[A(\n    '<<<x',\n    2\n)]\nclass X {}", "#[A(\n    '<<<x',\n    2\n)]\nclass X {}"},
		{"#[A(\n    \"<<<x\",\n    2\n)]\nclass X {}", "#[A(\n    \"<<<x\",\n    2\n)]\nclass X {}"},
		{"#[A('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy'), B(\n    1\n)]\nclass X {}", "#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy'\n), B(\n    1\n)]\nclass X {}"},
		{"#[A(\n    1\n), B('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy')]\nclass X {}", "#[A(\n    1\n), B('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy')]\nclass X {}"},
		{"#[A(\n    1\n)]\nclass X {}\nfoo('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy');", "#[A(1)]\nclass X {}\nfoo(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy'\n);"},
		{"#[Route('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', name: 'x',\n    methods: ['GET', 'POST'])]\nclass X {}", "#[Route(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    name: 'x',\n    methods: ['GET', 'POST']\n)]\nclass X {}"},
		{"#[A('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    ['b', 'c'])]\nclass X {}", "#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    ['b', 'c']\n)]\nclass X {}"},
		{"#[A('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 2,\n    [1, 2])]\nclass X {}", "#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    2,\n    [1, 2]\n)]\nclass X {}"},
		{"foo('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    [1, 2]);", "foo(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    [1, 2]\n);"},
		{"new Foo('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    [1, 2]);", "new Foo(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    [1, 2]\n);"},
		{"$x = [\"<<<$a\",\n    2];", "$x = [\"<<<$a\", 2];"},
		{"$x = [\"<<<{$a}\",\n    2];", "$x = [\"<<<{$a}\", 2];"},
		{"$x = [\"a<<<{$a}\",\n    2];", "$x = [\"a<<<{$a}\", 2];"},
		{"$x = [b\"<<<$a\",\n    2];", "$x = [b\"<<<$a\", 2];"},
		{"$x = [`<<<`,\n    2];", "$x = [`<<<`, 2];"},
		{"new Foo(\"<<<$a\",\n    2);", "new Foo(\"<<<$a\", 2);"},
		{"$x = [\"<<<\",\n    2];", "$x = [\"<<<\",\n    2];"},
		{"$x = ['<<<',\n    2];", "$x = ['<<<',\n    2];"},
		{"#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}", "#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}"},
		{"#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}", "#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}"},
		{"#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}", "#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}"},
		{"#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}", "#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}"},
		{"foo(\n    /** d */ 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n);", "foo(\n    /** d */ 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n);"},
		{"foo(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n);", "foo(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n);"},
		{"foo(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n);", "foo(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n);"},
		{"echo 1;\n#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}", "echo 1;\n#[A('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx')]\nclass X {}"},
		{"    foo(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n);", "    foo(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n);"},
		{"\nreturn [\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy',\n];", "\nreturn ['xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy',];"},
		{"\nreturn [\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy',\n];", "\nreturn ['xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy',];"},
		{"\nfoo(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy'\n);", "\nfoo('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy');"},
		{"\n\nreturn [\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy',\n];", "\n\nreturn ['xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy',];"},
		{"\n#[A(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'\n)]\nclass X {}", "\n#[A('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx')]\nclass X {}"},
		{"foo(\n    array\n(\n    1,\n    2\n),\n    3\n);", "foo(array\n(\n    1,\n    2\n), 3);"},
		{"#[A(\n    array\n(1,\n2),\n    3\n)]\nclass X {}", "#[A(array\n(1,\n2), 3)]\nclass X {}"},
		{"foo(\n    array (\n    1,\n    2\n),\n    3\n);", "foo(array (\n    1,\n    2\n), 3);"},
		{"?>\n<?=\nfoo(\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb'\n) ?>", "?>\n<?=\nfoo('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb') ?>"},
		{"eval(\n    /** d */ $a\n);", "eval(\n    /** d */ $a\n);"},
		{"exit( /** d */ $a);", "exit( /** d */ $a);"},
		{"die(/** d */\n    $a);", "die(/** d */\n    $a);"},
		{"eval(\n    $a\n);", "eval(\n    $a\n);"},
		{"exit(\n    1\n);", "exit(\n    1\n);"},
		{"die(\n    1\n);", "die(\n    1\n);"},
		{"\nreturn [\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy',\n];", "\nreturn [\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy',\n];"},
		{"\nreturn [\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy',\n];", "\nreturn [\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy',\n];"},
		{"\n\nreturn [\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy',\n];", "\n\nreturn [\n    'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',\n    'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy',\n];"},
		{"\n#[A('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy', )]\nclass X {}", "\n#[A('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx', 'yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy',)]\nclass X {}"},
	}
	for _, c := range cases {
		got, changed := apply(t, LineLength{}, "<?php\n"+c.src+"\n")
		if want := "<?php\n" + c.want + "\n"; got != want || changed != (c.src != c.want) {
			t.Errorf("%s\n got=%q changed=%v\nwant=%q", c.src, got, changed, want)
		}
	}
}
